mapper.select:
SELECT i.inquiry_no, i.inquiry_title, i.inquiry_status, i.inquiry_created, u.user_no, u.user_nickname, EXISTS ( SELECT 1 FROM tb_inquiry_file inf WHERE inf.inquiry_no = i.inquiry_no ) AS has_file FROM tb_inquiry i INNER JOIN tb_user u ON i.user_no = u.user_no
AND i.inquiry_status = #{inquiryStatus}
AND i.inquiry_title LIKE CONCAT('%', #{searchName}, '%')
AND u.user_nickname LIKE CONCAT('%', #{searchName}, '%')
ORDER BY i.inquiry_created DESC LIMIT #{pageSize} OFFSET #{startRowNum}

mapper.update:
UPDATE
    tb_inquiry
SET
    inquiry_status = #{inquiryStatus}
WHERE
    inquiry_no = #{inquiryNo}
